// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialCalls) public {
        // Bound initialCalls to a wide admissible domain that includes the max uint256.
        // We want to reach depositsCount == type(uint256).max to trigger the overflow bug.
        initialCalls = bound(initialCalls, 0, type(uint256).max);

        // Set up an actor and fund him with enough Ether for all calls.
        address actor = address(0x1234);
        vm.deal(actor, (initialCalls + 1) * 1 wei);

        // Advance depositsCount to initialCalls by repeatedly calling receive().
        vm.startPrank(actor);
        for (uint256 i = 0; i < initialCalls; i++) {
            (bool ok, ) = address(c).call{value: 1 wei}("");
            require(ok, "call failed");
        }

        // Now make one more call — this is the one that may trigger the bug.
        (bool ok, ) = address(c).call{value: 1 wei}("");
        require(ok, "final call failed");
        vm.stopPrank();

        // The general rule: depositsCount must equal the total number of successful receive() calls.
        // The reference contract maintains this invariant even when depositsCount is maxed out
        // (the require prevents the call). The buggy contract, however, allows the call and wraps depositsCount
        // back to 0, breaking the invariant.
        assertTrue(c.depositsCount() == initialCalls + 1);
    }
}

