pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 preCalls) public {
        // Bound depositAmount to a non-zero value to ensure meaningful deposits
        depositAmount = bound(depositAmount, 1, 1 ether);
        // Bound preCalls to a large number that could reach max depositsCount if repeated
        preCalls = bound(preCalls, 0, 2**256 - 2);

        // Record initial depositsCount
        uint256 initialCount = c.depositsCount();

        // Perform 'preCalls' deposits to drive depositsCount high
        for (uint256 i = 0; i < preCalls && i < 100; i++) {
            vm.deal(address(this), depositAmount);
            (bool success, ) = address(c).call{value: depositAmount}("");
            require(success, "pre-call deposit failed");
        }

        // Perform one final deposit that could trigger overflow in buggy version
        vm.deal(address(this), depositAmount);
        (bool finalSuccess, ) = address(c).call{value: depositAmount}("");

        // If the deposit succeeded (no revert), depositsCount must be strictly greater than initial
        // For reference: success always true (no overflow), depositsCount >= initialCount + preCalls + 1
        // For mutant: when overflow occurs, depositsCount wraps < initialCount, violating this property
        if (finalSuccess) {
            assertTrue(c.depositsCount() > initialCount);
        } else {
            // If it fails (only possible if require in reference catches overflow),
            // depositsCount must remain unchanged
            assertTrue(c.depositsCount() == initialCount);
        }
    }
}

