pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount, bytes memory data) public {
        // Restrict target to the adversarial reverting helper we deploy,
        // so the fuzzer cannot pick a random EOA that would always succeed.
        // The bug is about the modifier onlyOwner, but the difference shows
        // when the external call fails: reference reverts, bug does not.
        address ownerAddr = c.owner();
        vm.assume(ownerAddr != address(0));
        // We deploy a minimalist contract that always reverts on receiving ETH.
        Reverter reverter = new Reverter();
        target = address(reverter); // Override fuzzed target with the adversarial helper.
        // Give the contract some ETH so sendMoney has funds to forward.
        vm.deal(address(c), amount);
        // Record whether the call reverts.
        bool ok;
        // The modifier onlyOwner normally allows the call only from the owner.
        // If the caller is not the owner, the reference reverts on the modifier,
        // masking a potential failure of the external call.
        // To isolate the difference: call as the real owner so the modifier check passes on reference,
        // and the only difference is whether the modifier is strict or always-true.
        vm.prank(ownerAddr);
        try c.sendMoney(target, amount, data) {
            ok = true;
        } catch {
            ok = false;
        }
        // On reference: the reverter's fallback reverts, so the low-level call returns false,
        // but sendMoney does not check the return value, so the transaction itself succeeds (ok == true).
        // Actually, low-level call returns false on revert, but doesn't bubble up the revert.
        // So both reference and bug would NOT revert at the top level, ok == true in both cases.
        // That does not distinguish.
        // We need a difference that ONLY the modifier change creates.
        // Let's instead withdraw after sendMoney and check balance change?
        // The original difference statement: after a call to sendMoney(...), the value of state variable `withdrawAll` differs.
        // `withdrawAll` is a function, not a state variable. Probably they meant the effect of withdrawAll.
        // Let's reconsider: the modifier change makes withdrawAll callable by anyone.
        // The difference in the mut is: reference grants access only to owner; bug grants access to everyone.
        // We can test that directly: call withdrawAll from a non-owner and check revert.
        // But the requirement says: "Driven through the public/external entry sendMoney(...)".
        // So we must trigger the difference via sendMoney.
        // But sendMoney itself has onlyOwner, so if we call it from non-owner, reference reverts, bug succeeds.
        // That difference in revert can be observed.
        // However, the description says "after a call to sendMoney(...) completes, the value of state variable withdrawAll differs".
        // That implies sendMoney needs to succeed on both to observe the after-state.
        // So we must call sendMoney as the owner (so both succeed), and after that, some state change makes withdrawAll differ.
        // The onlyOwner modifier change does not affect state after sendMoney if called as owner.
        // The only change is who can call the function, not what it does.
        // So if we call sendMoney as owner, the state is identical between P and M.
        // The difference must be triggered when a non-owner calls sendMoney.
        // In reference, sendMoney reverts; in bug, it succeeds and potentially affects state.
        // So the "after a call to sendMoney(...) completes" means after a call that doesn't revert on the bug, but reverts on reference.
        // We can assert that the reference always reverts when called by non-owner, and the bug sometimes doesn't.
        // Universal property: For any non-owner sender, sendMoney always reverts on reference, and at least once does not revert on bug.
        // That directly uses the modifier bypass.
        // We don't need an adversarial helper; just check the revert flag with a non-owner sender.
        // Let's do that.
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

