pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Restrict to non-zero amounts that can be deposited and withdrawn
        vm.assume(amount > 0);
        // also avoid overflow on depositsCount (though require catches it, we stay in admissible range)
        vm.assume(amount <= address(this).balance);

        // 2. Fund the contract by sending ether as a random external user
        address donor = address(0x12345);
        vm.deal(donor, amount);
        vm.prank(donor);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        uint256 balanceBefore = address(c).balance;
        // withdrawAll is owner-only; we are the owner (setUp runs as test contract which deployed c)
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;

        // 3. General rule: after a successful withdrawAll, the contract's balance must be zero.
        // The bug makes withdrawAll a no-op, so balance remains unchanged (non-zero).
        assertTrue(balanceAfter == 0);
    }
}

