pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // restrict to safe deposit amounts
        vm.assume(amount > 0 && amount <= type(uint96).max);
        // fund contract by sending ether to receive()
        vm.deal(address(this), amount);
        address(c).call{value: amount}("");
        // record owner's pre-withdraw balance
        address own = c.owner();
        uint256 beforeBal = own.balance;
        uint256 contractBal = address(c).balance;
        // owner calls withdrawAll
        vm.prank(own);
        c.withdrawAll();
        // assert owner's balance increased exactly by previous contract balance
        assertTrue(own.balance == beforeBal + contractBal);
    }
}

